 "content": "def transform(grid):
    """Restore the masked triangular shift of a cyclic color row."""
    n = max(max(row) for row in grid)
    start = next((v for v in grid[0] if v), None)
    if start is None:
        raise ValueError("cannot infer the color cycle from an empty first row")
    base = [((start - 1 + c) % n) + 1 for c in range(len(grid[0]))]
    out = []
    for r, row in enumerate(grid):
        out.append([((base[c] % n) + 1) if c < r else base[c]
                    for c in range(len(row))])
    return out
